import React, { useState, useRef } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';

export default function TeacherDashboard() {
  const { user, logout, API } = useAuth();
  const nav = useNavigate();
  const [subj, setSubj] = useState('');
  const [qr, setQr] = useState(null);
  const [sess, setSess] = useState(null);
  const [cd, setCd] = useState(0);
  const [ld, setLd] = useState(false);
  const [err, setErr] = useState('');
  const cr = useRef(null);

  const gen = async (e) => {
    e.preventDefault();
    if (!subj.trim()) return;
    setLd(true); setErr(''); setQr(null); setSess(null);
    try {
      const r = await API.post('/qr/generate', { subject: subj });
      setQr(r.data.qr);
      setSess(r.data.session);
      setCd(r.data.session.ttlSeconds);
      if (cr.current) clearInterval(cr.current);
      cr.current = setInterval(() => setCd((p) => p <= 1 ? 0 : p - 1), 1000);
    } catch (e) { setErr(e.response?.data?.message || 'Failed'); }
    finally { setLd(false); }
  };

  const doLogout = () => { logout(); nav('/login'); };

  const wrapper = {
    minHeight: '100vh', padding: 20,
    background: 'linear-gradient(135deg, #0f0c29, #302b63, #24243e)',
    color: '#fff'
  };
  const row = { display: 'flex', justifyContent: 'space-between', marginBottom: 20 };
  const btn = { padding: '8px 16px', background: 'transparent', border: '1px solid rgba(255,255,255,0.2)', borderRadius: 6, color: '#ff6b6b', cursor: 'pointer' };
  const errBox = { background: 'rgba(255,50,50,0.15)', padding: 10, borderRadius: 8, color: '#ff6b6b', marginBottom: 16 };
  const card = { background: 'rgba(255,255,255,0.06)', borderRadius: 12, padding: 24, marginBottom: 20 };
  const inp = { padding: 12, borderRadius: 8, border: '1px solid rgba(255,255,255,0.15)', background: 'rgba(255,255,255,0.06)', color: '#fff', fontSize: 16 };
  const primaryBtn = { padding: 12, borderRadius: 8, border: 'none', background: '#6c63ff', color: '#fff', fontSize: 16, fontWeight: 600, cursor: 'pointer' };
  const formRow = { display: 'flex', flexDirection: 'column', gap: 12 };
  const liveBadge = { background: '#ff4444', color: '#fff', padding: '4px 12px', borderRadius: 20, fontSize: 12, fontWeight: 700 };

  return React.createElement('div', { style: wrapper },
    React.createElement('div', { style: row },
      React.createElement('h1', { style: { margin: 0 } }, 'Teacher Dashboard'),
      React.createElement('button', { onClick: doLogout, style: btn }, 'Logout')
    ),
    err ? React.createElement('div', { style: errBox }, err) : null,
    React.createElement('div', { style: { maxWidth: 500, margin: '0 auto' } },
      React.createElement('div', { style: card },
        React.createElement('h2', { style: { marginTop: 0 } }, 'Generate QR'),
        React.createElement('form', { onSubmit: gen, style: formRow },
          React.createElement('input', { value: subj, onChange: (e) => setSubj(e.target.value), placeholder: 'Subject name', style: inp, required: true }),
          React.createElement('button', { type: 'submit', disabled: ld, style: primaryBtn }, ld ? '...' : 'Generate QR')
        )
      ),
      qr && sess ? React.createElement('div', { style: { ...card, textAlign: 'center' } },
        React.createElement('div', { style: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 } },
          React.createElement('h2', { style: { margin: 0 } }, 'Scan QR'),
          React.createElement('span', { style: liveBadge }, 'LIVE')
        ),
        React.createElement('img', { src: qr, alt: 'QR', style: { width: 220, height: 220, background: '#fff', padding: 8, borderRadius: 8 } }),
        React.createElement('p', { style: { marginTop: 12 } }, sess.subject, ' \u00b7 Expires in ', React.createElement('strong', { style: { color: cd < 10 ? '#ff6b6b' : '#6c63ff', fontSize: 22 } }, cd, 's'))
      ) : null
    )
  );
}
